'use strict';
const page = document.body.dataset.page;
const main = document.getElementById('main');
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photo = (name,alt,extra='') => `<img src="assets/images/${esc(name)}.webp" alt="${esc(alt)}" ${extra}>`;
const colourBoard = () => `<div><div class="material-board" role="img" aria-label="Illustrative colour studies in indigo, faded blue, brown and beige"><div class="swatch">Indigo</div><div class="swatch">Faded blue</div><div class="swatch">Earth</div><div class="swatch">Warm neutral</div></div><div class="board-caption">Colour study / illustrative palette, not photographed materials</div></div>`;
const cards = projects => `<div class="project-grid">${projects.map((p,i)=>`<a class="project-card" href="project.html?id=${encodeURIComponent(p.id)}"><div class="project-cover">${photo(p.image,p.alt,'loading="lazy" width="1200" height="1000"')}</div><div class="project-meta"><div><h3>${esc(p.title)}</h3><p>${esc(p.category)} · ${esc(p.stage)}</p></div><span class="project-index">0${i+1} ↗</span></div></a>`).join('')}</div>`;
const milestones = data => `<div class="milestones">${data.milestones.map(m=>`<div class="milestone"><h3>${esc(m.title)}</h3><p>${esc(m.detail)}</p></div>`).join('')}</div>`;
function chrome(data){
 const links=[['about','About','✷'],['collections','Collections','↗'],['studio','Studio','✂'],['inspiration','Inspiration','✧'],['impact','Impact','↻'],['journal','Upcoming','✧'],['contact','Contact','✉']];
 document.getElementById('header').innerHTML=`<nav class="nav" aria-label="Main navigation"><a href="index.html" class="logo" aria-label="ROHENI Studio home"><img src="assets/images/roheni-logo.png" alt="ROHENI" width="140" height="67"></a><a href="index.html" class="home-token" aria-label="Home"><span>✳</span> HOME</a><button class="menu-button" aria-expanded="false" aria-controls="nav-links">Menu +</button><div class="nav-links" id="nav-links">${links.map(([id,title,symbol])=>`<a href="${id}.html" ${page===id?'aria-current="page"':''}><span aria-hidden="true">${symbol}</span>${title}</a>`).join('')}</div></nav><div class="site-controls"><fieldset class="theme-picker"><legend>Pick your mood</legend><button type="button" data-theme-choice="white" aria-pressed="true">Paper</button><button type="button" data-theme-choice="red" aria-pressed="false">Red</button><button type="button" data-theme-choice="dark" aria-pressed="false">Charcoal</button></fieldset><button type="button" class="motion-control" aria-pressed="false">Pause motion Ⅱ</button></div>`;
 document.getElementById('footer').innerHTML=`<div class="footer"><div class="footer-top"><div><p class="eyebrow">Rooted here, Nairobi</p><h2>There’s more<br>to <em>make.</em></h2></div><a class="text-link" href="mailto:${esc(data.brand.email)}">Start a conversation ↗</a></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ROHENI Studio</span><div class="footer-links"><a href="${esc(data.brand.instagram)}" target="_blank" rel="noopener noreferrer">Instagram ↗</a><a href="contact.html">Contact</a><a href="#main">Back to top ↑</a></div></div></div>`;
 const btn=document.querySelector('.menu-button');const nav=document.querySelector('.nav-links');
 const close=()=>{btn.setAttribute('aria-expanded','false');nav.classList.remove('open');btn.textContent='Menu +';document.body.classList.remove('menu-open');};
 btn.addEventListener('click',()=>{const open=btn.getAttribute('aria-expanded')!=='true';btn.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);btn.textContent=open?'Close −':'Menu +';document.body.classList.toggle('menu-open',open);});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();btn.focus();}});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));
 matchMedia('(min-width: 1101px)').addEventListener('change',e=>{if(e.matches)close();});
}
function movingBanner(){const words='REIMAGINE <i>✳</i> RECONSTRUCT <i>✳</i> REPEAT <i>✳</i> MADE IN NAIROBI <i>✳</i>';return `<div class="ticker" aria-label="Reimagine. Reconstruct. Repeat. Made in Nairobi."><div class="ticker-track" aria-hidden="true"><span>${words}</span><span>${words}</span></div></div>`;}
function heroDoodles(){return `<svg class="hero-doodles" viewBox="0 0 1200 720" fill="none" aria-hidden="true"><g stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M40 100q45-70 92-7t86 0m-44-22 45 22-38 26"/><path d="m1060 50 10 28 30 3-24 18 7 30-24-17-25 16 9-29-22-20 30-1Z"/><path d="m220 580 25-18 25 15 33-5 28 34-16 23-16-18-2 57-69 2 3-60-17 16-19-20 25-26m25-18 5 29 20-14"/><path d="M960 615c70-80 100 70 160-5m-90-25 9 18m13-27 12 18m15-27 13 18"/><ellipse cx="109" cy="280" rx="55" ry="17" transform="rotate(-22 109 280)"/><path d="m57 301 103-41m-83 21 8 10m10-18 8 10m10-18 8 10"/></g></svg>`;}
function bentLogo(){return `<canvas class="bent-logo" width="1200" height="620" role="img" aria-label="Original ROHENI logo, gently curved">ROHENI</canvas>`;}
function founderWorld(){return `<a class="founder-world globe-full" href="studio.html" aria-label="Read Rita’s story, from childhood to ROHENI">${bentLogo()}<svg class="world-sphere" viewBox="0 0 600 600" aria-hidden="true"><defs><clipPath id="sphere-clip"><circle cx="300" cy="300" r="255"/></clipPath></defs><g clip-path="url(#sphere-clip)" fill="none" stroke="currentColor" stroke-width="1.25"><circle cx="300" cy="300" r="255"/><ellipse cx="300" cy="300" rx="175" ry="255"/><ellipse cx="300" cy="300" rx="80" ry="255"/><ellipse cx="300" cy="300" rx="255" ry="75"/><ellipse cx="300" cy="300" rx="255" ry="170"/><path d="M45 300h510M300 45v510"/><g fill="currentColor" opacity=".18" stroke="none"><path d="m262 222 35-25 38 6 22 29 34 15-15 35-18 8-12 49-31 41-20-16-15-55-29-12-24-36 5-25Z"/><path d="m350 151 38-46 49 9 42 31 31 47-13 49-41 6-20-25-43-15-19-29Z M123 120l41-18 43 13 27 30-22 36-41 10-7 34-27-4-19-47Z M166 259l36-20 32 21 3 45-22 33-15 55-20 8-8-59-19-35Z M407 398l42-17 41 20 8 30-27 17-43-7-24-19Z M373 335l12-9 7 30-16 27-10-17Z"/></g></g></svg><img class="child-cutout" src="assets/images/founder-child-cutout.png" alt="Childhood photograph." loading="lazy"><span class="world-note">Before the brand,<br>there was me. ↗</span></a>`;}
function home(data){return `<section class="play-hero"><div class="hero-top eyebrow"><span>Independent by design</span><span>Wear a different story.</span></div><div class="hero-stage"><h1>Nothing about us<br><em>is ordinary.</em></h1>${heroDoodles()}<button type="button" class="flying-play" aria-label="Play soundtrack" aria-pressed="false"><span aria-hidden="true">▷</span><small>Alexa, give this a soundtrack.</small></button><a class="scrap scrap-denim" href="project.html?id=kaleidoscope">${photo('denim-campaign','Explore Kaleidoscope patchwork denim jackets','fetchpriority="high"')}<span>01 / Kaleidoscope ↗</span></a><a class="scrap scrap-adwoa" href="project.html?id=adwoa">${photo('women-set','Explore the Adwoa set')}<span>04 / Adwoa ↗</span></a><a class="hero-person" href="project.html?id=the-herd" aria-label="Discover The Herd"><img src="assets/images/herd-cutout.png" alt="The Herd cowhide jacket campaign portrait." fetchpriority="high"></a><a class="round-stamp" href="collections.html"><span class="stamp-small"All Kenyan.</span><strong>ALL<br>ROHENI.</strong><span class="stamp-arrow" aria-hidden="true">↗</span></a><span class="handnote">look closer,<br> that's the good bit.</span></div><div class="hero-bottom"><p>Overlooked materials.<br>Extraordinary clothes.</p><a class="text-link" href="#story">Pull on this thread ↓</a></div></section>${movingBanner()}<section class="section intro" id="story"><p class="eyebrow">A different way of seeing / 01</p><div><h2>Some see leftovers.<br>We see the <em>next look.</em></h2><p>Factory cutoffs. Faded denim. Materials someone else has finished with. At ROHENI, they are the beginning of something worth wearing.</p><p>We are a Nairobi fashion studio celebrating African artistry, individuality and the imagination of Kenyan makers. Our ambition is to help reduce waste around Gikomba, one considered material decision at a time.</p><a class="text-link" href="about.html">This is ROHENI ↗</a></div></section><section class="section collection-chapters"><div class="section-head"><div><p class="eyebrow">Collection 001</p><h2>Meet the<br><em>characters.</em></h2></div><p>Different textures. Shared spirit.<br>Choose a story to step inside.</p></div>${collectionChapters(data)}</section>${missionTeaser()}${inspirationTeaser()}<section class="section studio-invite">${founderWorld()}<div><p class="eyebrow">The person behind the pieces</p><h2>Some things<br>I say through<br><em>clothes.</em></h2><p>I’m Rita. I’ve always loved the freedom of dressing a little differently. What I cannot quite put into words, I often let clothes say for me.</p><p>ROHENI grew from that feeling. The belief that what gets passed over can still hold something extraordinary. This is my way of giving it room to be seen.</p><a class="text-link" href="studio.html">Meet the person behind the pieces ↗</a><br><a class="text-link" href="process.html">Follow the thread ↗</a></div></section><section class="section journal-feature"><div><p class="eyebrow">Collection 002 / in development</p><h2>The next<br><em>beautiful idea.</em></h2><p>Patchwork outerwear, a hoodie made from secondhand material and a premium recycled T-shirt direction. Follow the choices taking Collection 002 from an image to something we can make and wear.</p><a class="text-link" href="journal.html">Open the work in progress ↗</a></div>${developmentPreview(data)}</section><section class="section"><p class="eyebrow">Small beginnings. Real momentum.</p>${milestones(data)}</section>`;}
function collectionChapters(data){return data.projects.map((p,i)=>`<article class="collection-chapter" id="${esc(p.id)}"><a class="chapter-image" href="project.html?id=${esc(p.id)}">${photo(p.image,p.alt,'loading="lazy"')}<span class="chapter-number">0${i+1}</span></a><div class="chapter-copy"><p class="eyebrow">${esc(p.category)} / Collection 001</p><h2>${esc(p.title)}</h2><p class="chapter-subtitle">${esc(p.subtitle)}</p><p class="chapter-narrative">${esc(p.intro)}</p><a class="text-link" href="project.html?id=${esc(p.id)}">The story & the pieces ↗</a></div></article>`).join('');}
function aboutCarousel(){const slides=[['campaign','Collection I / the first gathering'],['carousel-kaleidoscope-front','Kaleidoscope / colour in conversation'],['carousel-kaleidoscope-back',' Kaleidoscope / another point of view'],['carousel-herd',' The Herd / distinct, together'],['atir-orange-front','AtIr / Collection 001'],['atir-orange-profile','AtIr / cut, volume and movement'],['carousel-statement-group','Statement tees / the studio community'],['carousel-statement-hangers','Statement tees / a voice of their own'],['carousel-statement-portrait','Statement tees / wearing your words'],['carousel-statement-studio','Statement tees / from the archive']];return `<div class="campaign-carousel" role="region" aria-roledescription="carousel" aria-label="ROHENI campaign photographs"><div class="campaign-window"><div class="campaign-track">${slides.map(([im,caption],i)=>`<figure class="campaign-slide" role="group" aria-roledescription="slide" aria-label="${i+1} of ${slides.length}" aria-hidden="${i!==0}">${photo(im,caption,i?'loading="lazy"':'loading="eager"')}<figcaption>${caption}</figcaption></figure>`).join('')}</div></div><div class="carousel-controls"><button type="button" data-carousel-prev aria-label="Previous campaign photo">←</button><p data-carousel-count aria-live="off">01 / ${String(slides.length).padStart(2,'0')}</p><button type="button" data-carousel-next aria-label="Next campaign photo">→</button><button type="button" data-carousel-pause aria-pressed="false">Pause slideshow Ⅱ</button></div></div>`;}
function setupCarousel(){const root=document.querySelector('.campaign-carousel');if(!root)return;const slides=[...root.querySelectorAll('.campaign-slide')],track=root.querySelector('.campaign-track'),pause=root.querySelector('[data-carousel-pause]');let index=0,userPaused=false,hover=false,focus=false,visible=false;const show=n=>{index=(n+slides.length)%slides.length;track.style.transform=`translateX(-${index*100}%)`;slides.forEach((s,i)=>s.setAttribute('aria-hidden',String(i!==index)));root.querySelector('[data-carousel-count]').textContent=`${String(index+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}`;};pause.addEventListener('click',()=>{userPaused=!userPaused;pause.setAttribute('aria-pressed',String(userPaused));pause.textContent=userPaused?'Play slideshow ▷':'Pause slideshow Ⅱ';});root.querySelector('[data-carousel-prev]').addEventListener('click',()=>show(index-1));root.querySelector('[data-carousel-next]').addEventListener('click',()=>show(index+1));root.addEventListener('mouseenter',()=>hover=true);root.addEventListener('mouseleave',()=>hover=false);root.addEventListener('focusin',()=>focus=true);root.addEventListener('focusout',e=>{focus=root.contains(e.relatedTarget);});root.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(index+(e.key==='ArrowRight'?1:-1));}});let touchX;root.addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});root.addEventListener('touchend',e=>{if(touchX===undefined)return;const delta=e.changedTouches[0].clientX-touchX;if(Math.abs(delta)>55)show(index+(delta<0?1:-1));touchX=undefined;},{passive:true});new IntersectionObserver(es=>visible=es[0].isIntersecting,{threshold:.2}).observe(root);setInterval(()=>{if(!userPaused&&!motionPaused&&!hover&&!focus&&visible&&!document.hidden)show(index+1);},5500);}

function about(data){return `<section class="page-intro"><p class="eyebrow">About / ROHENI </p><h1>We have a thing<br>for the <em>overlooked.</em></h1><p>A torn pair of jeans. A factory cutoff. A hide with an awkwardly placed marking. We are drawn to materials that ask us to think a little harder before we cut.</p></section><section class="section story-layout"><div class="about-story-media"><h2>A point of view.<br><em>Made here.</em></h2><figure class="event-film"><video muted loop playsinline controls preload="none" poster="assets/images/roheni-event-poster.webp" aria-label="ROHENI fashion event footage"><source src="assets/media/roheni-event.mp4" type="video/mp4"></video><button type="button" class="event-sound-toggle" aria-pressed="false">Sound on ♫</button><figcaption>A little of our world, in motion.</figcaption></figure></div><div><p>ROHENI is a Kenyan Sustainable fashion brand founded by Rita Roheni. We make expressive clothing and accessories from factory cutoffs, discarded garments, and overlooked materials. Our first collection brought together Kaleidoscope patchwork denim, The Herd cowhide jackets, the AtIr and Adwoa women’s sets, and accessories.</p><p>What connects them is a way of looking: colour against colour, a surprising opening, a surface you want to touch. We want people to choose our clothes because they love them. The material story is part of why they matter, and the making has to live up to that promise.</p><p>Our love of African artistry is grounded in the people working here. It is their judgement, skill and willingness to work through an unusual idea that let a drawing become a garment. For visitors discovering Kenyan creativity, we hope a ROHENI piece becomes something personal to take home.</p><a class="text-link" href="collections.html">Explore Collection 001 ↗</a></div></section><section class="section">${aboutCarousel()}</section><section class="section story-layout"><h2>Clothes worth<br><em>keeping.</em></h2><div><p>Gikomba is a place of livelihoods, resourcefulness and style. It is also close to a waste problem that no single label can solve. Our part begins with choosing usable material, designing for it and showing how much more it can become.</p><p>We are still building the records that will let us account for that work properly. Until then, our collections show the creative response; our impact page separates the wider evidence from the contribution we can honestly claim.</p><a class="text-link" href="impact.html">Read the material and waste story ↗</a></div></section>`;}

function studio(data){return `<section class="page-intro"><p class="eyebrow">The studio/ Nairobi, Kenya </p><h1>A little curiosity.<br>A different <em>future.</em></h1></section><section class="section section-compact portrait-layout">${photo('rita','Rita Gathoni, portrait supplied in the ROHENI portfolio','loading="lazy"')}<div><p class="eyebrow">The story behind ROHENI</p><h2>It started<br>with <em>looking.</em></h2><p>Before ROHENI, I was a serial thrifter. I loved finding an unusual fabric, a forgotten garment or a piece that could become something else.</p><p>In Gikomba, that curiosity met a larger question. Alongside the creativity and livelihoods of the market, I saw materials being left behind. I wanted to explore what could happen if we looked at them differently.</p><p>ROHENI became a way to turn that instinct into clothes: expressive pieces that let the material’s past become part of its new identity.</p></div></section><section class="section red-section"><div class="story-layout"><h2>Rooted here.<br>Made to <em>travel.</em></h2><div><p>Our work celebrates African artistry through the imagination and skill of Kenyan makers. We want that work to be seen, appreciated, and valued.</p><p>For visitors discovering Kenya, a jacket, set or accessory can offer a tangible encounter with that creativity. For local customers, it is work made here, presented with care and confidence.</p><p>We have worked with Fairmont The Norfolk and Fairmont’s Nanyuki property as we develop collaborations and reach new audiences.</p></div></div></section><section class="section"><div class="section-head"><div><p class="eyebrow">Progress, with room to grow</p><h2>One collection.<br>A beginning.</h2></div></div>${milestones(data)}</section><section class="section section-compact story-layout"><h2>A practice<br>still <em>learning.</em></h2><div><p>We source factory cutoffs and waste materials. As the studio develops, we are working toward clearer records of each material’s source, use and remaining offcuts.</p><p>Reducing pollution around Gikomba is a goal. We do not yet publish a measured waste-diversion total. The next step is to document our contribution as carefully as we develop the garments.</p></div></section>`;}
function journal(data){return `<section class="page-intro"><p class="eyebrow">Collection 002 / in development</p><h1>The material<br>comes <em>first.</em></h1><p>The next collection carries our patchwork language into a wider wardrobe: denim and cowhide jackets, a hoodie made from secondhand material, a premium recycled T-shirt direction and unisex Kowloon pants. More ways to wear ROHENI, with the same attention to what already exists.</p><span class="stage">Design development / not yet launched</span></section><section class="section section-compact journal-layout">${developmentPreview(data)}<div><p class="eyebrow">From Collection 001 to 002</p><h2>Keep the character.<br><em>Refine the making.</em></h2><p>We are keeping what made the first collection feel like us: visible contrasts, a willingness to cut differently and clothes with a strong presence. This time, curves move through the patchwork, pockets take less familiar shapes and the silhouette needs to work across different bodies.</p><p>With cowhide, the markings still lead the conversation. We want smooth leather and hair-on surfaces to meet with intention, whether a jacket is cropped or full length. With denim, we are working towards a balance between a surprising arrangement and a fit someone reaches for repeatedly.</p><p>Sampling is where those intentions are tested. Sleeve length, body length, panel position and movement all need to be resolved in the garment, not only in the image.</p></div></section><section class="section kowloon-direction"><div><p class="eyebrow">Collection 002 / Kowloon pants</p><h2>Room to move.<br><em>Your way.</em></h2><p>Kowloon began with Rita’s interest in Hong Kong streetwear: wide trousers, loose layers and the freedom to make a silhouette your own. That reference becomes a unisex direction for ROHENI, with generous volume through the leg and a relaxed outline.</p><p>We imagine them with a fitted tank, an oversized tee or a cropped jacket. The mood is futuristic underground streetwear, but the appeal is everyday freedom: dress them up, wear them loose, change the proportions around them.</p><p>These images explore the intended shape on different bodies. Fabric, sizing, construction, and material sourcing still need to be resolved through sampling.</p><span class="stage">Digital concepts / Collection 002 in development</span></div><div class="kowloon-pair"><figure>${photo('kowloon-male-concept','Male styling concept of dark wide-leg Kowloon pants with a black tank top','loading="lazy"')}<figcaption>Digital concept 1</figcaption></figure><figure>${photo('kowloon-female-concept','Female styling concept of dark wide-leg Kowloon pants with a black tank top','loading="lazy"')}<figcaption>Digital concept 2</figcaption></figure></div></section><section class="section collection002-directions"><div class="section-head"><div><p class="eyebrow">New directions / everyday pieces, considered</p><h2>A wider<br><em>ROHENI wardrobe.</em></h2></div></div><article class="direction-feature" id="patchwork-hoodie"><div class="direction-pair"><figure>${photo('hoodie-full-concept','Full-length styling concept of a curved patchwork hoodie','loading="lazy"')}<figcaption>Digital styling concept</figcaption></figure><figure>${photo('hoodie-detail-concept','Close view of the mustard hood and cream, rust and deep teal curved hoodie panels','loading="lazy"')}<figcaption>Colour and panel direction </figcaption></figure></div><div><p class="eyebrow">002 / the patchwork hoodie</p><h2>A softer place<br>for <em>patchwork.</em></h2><p>The hoodie takes our love of contrast into something relaxed and familiar. In the concept, cream curves travel between rust and deep teal, while a mustard hood draws the colour upwards. The panels feel fluid rather than like a conventional square grid.</p><p>We plan to build it from suitable secondhand material. That means sorting for condition, weight and compatibility before cutting; a strong colour combination alone is not enough if the fabrics behave differently in wear or washing.</p><p>The hood is part of the design, not an afterthought. Our construction study uses two mirrored halves and an overlapping front. The proposed overlap still needs to be tested on a physical sample, alongside the fit, cuffs and pocket placement.</p></div></article><figure class="hood-construction">${photo('hoodie-construction','Hood construction study with centre crown seam, two mirrored halves and a proposed 6 centimetre overlap','loading="lazy"')}<figcaption>Construction study / proposed 6 cm front overlap for sampling, not a final production pattern.</figcaption></figure><article class="direction-feature tee-direction" id="recycled-tshirts"><figure>${photo('collection002-tee','White ROHENI T-shirt, neck label and hang-tag development mockup','loading="lazy"')}<figcaption>Product mockup</figcaption></figure><div><p class="eyebrow">002 / premium recycled T-shirts</p><h2>The quiet piece<br>still needs <em>care.</em></h2><p>Alongside the louder patchwork, we want a T-shirt that holds its own through cut, feel and finishing. The mockup brings the attention close: a clean neckline, the ROHENI label and the small details someone notices while dressing.</p><p>This is our premium recycled T-shirt direction for Collection 002. We are developing the material specification and want the finished piece to feel substantial and comfortable, whether worn alone or under one of our jackets.</p><p>Reconstructing a garment and making new fabric from recycled fibres are different processes. We will describe the final T-shirt according to the material actually sourced, with fibre composition and recycled-content percentage confirmed before release.</p><p class="small-text">Development stage / material specification and production sample pending.</p></div></article></section>${developmentGallery(data)}<section class="section story-layout"><h2>What we need<br>to <em>learn next.</em></h2><div><p>For every direction, the next step is a sample that can be handled, fitted and revised. We need to see how the fabrics join, how a sleeve moves and how the piece responds to wear and care.</p><p>We also want to record the material source, weight used and offcuts remaining. That will help us make better decisions and describe our material use with evidence. These are development goals, not impact already measured.</p><a class="text-link" href="contact.html">Discuss development or collaboration ↗</a></div></section>`;}

function project(data){const id=new URLSearchParams(location.search).get('id');const p=data.projects.find(x=>x.id===id);if(!p){document.title='Project not found | ROHENI';return `<section class="page-intro"><p class="eyebrow">Project not found</p><h1>Let’s pick up<br>another thread.</h1><p><a class="text-link" href="collections.html">View all projects ↗</a></p></section>`;}document.title=`${p.title} | ROHENI Studio`;return `<section class="page-intro"><p class="eyebrow"><a href="collections.html">Work</a> / ${esc(p.stage)}</p><h1>${esc(p.title)}</h1><p>${esc(p.subtitle)}</p></section><section class="project-hero">${photo(p.image,p.alt,'fetchpriority="high"')}<div class="project-facts"><span>${esc(p.year)}</span><span>${esc(p.category)}</span><span>Nairobi, Kenya</span></div></section><section class="section section-compact story-layout"><h2>The story<br>of the <em>piece.</em></h2><div><p>${esc(p.intro)}</p>${p.sections.map(s=>`<article class="story-block" style="margin-top:35px"><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></article>`).join('')}</div></section><section class="section section-compact"><div class="gallery">${p.gallery.map(g=>`<figure><button class="image-button" data-full="assets/images/${esc(g.image)}.${esc(g.ext||'webp')}" data-caption="${esc(g.caption)}" aria-label="Enlarge image: ${esc(g.caption)}"><img src="assets/images/${esc(g.image)}.${esc(g.ext||'webp')}" alt="${esc(g.caption)}" loading="lazy"></button><figcaption>${esc(g.caption)}</figcaption></figure>`).join('')}</div><p class="credits-note">Images from the studio’s collection archive. For making, photography and collaboration enquiries, contact the studio.</p><a class="text-link next-project" href="collections.html">Explore the other collections ↗</a></section>`;}
function contact(data){return `<section class="page-intro"><p class="eyebrow">Contact</p><h1>Something<br>on your <em>mind?</em></h1><p>For creative collaborations, press, styling and conversations about the work.</p></section><section class="section contact-layout"><div><div class="contact-line"><p class="eyebrow">Email</p><a href="mailto:${esc(data.brand.email)}">${esc(data.brand.email)} ↗</a></div><div class="contact-line"><p class="eyebrow">Instagram</p><a href="${esc(data.brand.instagram)}" target="_blank" rel="noopener noreferrer">@rohenistudio ↗</a></div><div class="contact-line"><p class="eyebrow">Based in</p><p>Nairobi, Kenya</p></div></div><div>${photo('studio-campaign','Group portrait of models in ROHENI garments.','loading="lazy"')}</div></section>`;}
function galleryMarkup(items){return `<div class="gallery">${items.map(g=>`<figure data-kind="${esc(g.type||'Archive')}" class="${g.image==='concept-atir'?'original-concept':''}"><button class="image-button" data-full="assets/images/${esc(g.image)}.${esc(g.ext||'webp')}" data-caption="${esc(g.caption)}" aria-label="Enlarge image: ${esc(g.caption)}"><img src="assets/images/${esc(g.image)}.${esc(g.ext||'webp')}" alt="${esc(g.caption)}" loading="lazy"></button><figcaption>${g.type?`<span class="gallery-label">${esc(g.type)}</span>`:''}${esc(g.caption)}</figcaption></figure>`).join('')}</div>`;}
function developmentPreview(data){return `<figure class="development-preview"><div><img src="assets/images/concept-herd-female-seamless.webp" alt="cowhide jacket concept on a female model; not a finished garment" loading="lazy"></div><figcaption>Collection 002 / cowhide direction ·<br>Design in development · garment not yet produced</figcaption></figure>`;}
function developmentGallery(data){return `<section class="section section-compact"><div class="section-head"><div><p class="eyebrow">Collection 002</p><h2>The studies<br>behind the <em>pieces.</em></h2></div><p class="small-text">Concepts, diagrams and material directions.</div><div class="gallery-filters" role="group" aria-label="Filter development images">${['All','Digital concept','Design study','Construction study','Product direction'].map((v,i)=>`<button type="button" data-filter="${v}" aria-pressed="${i===0}">${i===0?'All studies':v}</button>`).join('')}</div><div id="development-gallery">${galleryMarkup(data.development)}</div></section>`;}

function processPage(data){return `<section class="page-intro"><p class="eyebrow">The making / studio archive</p><h1>From overlooked<br>to <em>reimagined.</em></h1><p>Materials, drawings and the work of making. A closer look at how a piece begins to take shape.</p></section><section class="section section-compact">${galleryMarkup(data.process)}</section><section class="section red-section"><div class="story-layout"><h2>Made through<br><em>collaboration.</em></h2><div><p>Every design needs a conversation between the idea, the material and the people making it. Pattern development, cutting, stitching and fitting give that conversation a physical form.</p><p>Our next step is to document the material source, maker contributions and sample revisions more consistently, so that the story behind each garment stays connected to the finished piece.</p><a class="text-link" style="margin-top:25px" href="journal.html">See what we are developing next ↗</a></div></div></section>`;}
function missionTeaser(){return `<section class="section mission-teaser"><div><p class="eyebrow">Impact / Gikomba and the material question</p><h2>Before we cut,<br>we look at<br><em>what remains.</em></h2><p>Secondhand clothing is part of everyday life in Nairobi. It supports businesses, gives people affordable choices and keeps garments in use. But when the unwanted pieces keep arriving, the cost of dealing with them stays here.</p><p>Our response starts at the cutting table: choose usable material, give it a considered design and make something someone wants to keep. The larger story asks more of the fashion system, too.</p><a class="text-link" href="impact.html">Gikomba, the evidence & our response ↗</a></div><figure class="mission-photo impact-cover">${photo('impact-waste-site','Reference photograph of people sorting mixed waste at a smoky open waste site','loading="lazy"')}<figcaption>Nairobi waste site in Gikomba Market.</figcaption><button class="orbit-icon" type="button" data-cycle-material aria-label="Cycle material inspiration"><span aria-hidden="true">↻</span><small>rethink it</small></button></figure></section>`;}

function inspirationTeaser(){return `<section class="section inspiration-teaser"><div><p class="eyebrow">Inspiration / where the eye goes first</p><h2>It starts with<br><em>a surface.</em></h2><p>We love the part of a cowhide marking that will not repeat, the soft fade in worn denim and the tension between a smooth panel and a rougher one. These observations shape the pieces before there is a complete sketch.</p><p>The board also holds creative references: people whose ways of thinking help us question a familiar object and develop our own point of view.</p><a class="text-link" href="inspiration.html">Materials, influences & our response ↗</a></div><a href="inspiration.html" class="teaser-collage" aria-label="Explore ROHENI’s inspiration board"><img src="assets/images/inspiration-hide-source.webp" alt="Studio-supplied reference showing stacked hair-on hides" loading="lazy"><img src="assets/images/board-denim.png" alt="Denim seam and wear reference" loading="lazy"><span>start with what catches your eye</span></a></section>`;}

const boardItems=[['inspiration-hide-source.webp','01 / Cowhide','Irregular markings and hair-on texture.'],['concept-herd-female-seamless.webp','02 / Silhouette',' ROHENI Collection 002.'],['board-denim.png','03 / Denim','Seams, weight, worn colour.'],['board-belts.png','04 / Hardware','Buckles. Patina. Repetition.'],['board-leather.png','05 / Leather','Soft surface. Strong presence.'],['board-bandana.png','06 / Pattern','Rhythm beyond the garment.'],['lummi-fabric.jpg','07 / New surfaces','Amino / Lummi.'],['lummi-denim.jpg','08 / Proportion','Deep Patel / Lummi .']];
function inspirationPage(){return `<section class="page-intro"><p class="eyebrow">Inspiration </p><h1>We keep coming<br>back to <em>texture.</em></h1><p>Cowhide, worn denim, leather, hardware. Materials with enough character to interrupt a familiar silhouette. This board shows what catches our attention and how we try to turn a reference into a decision of our own.</p></section><section class="section section-compact inspiration-reading"><article><p class="eyebrow">01 / why cowhide stays with us</p><h2>Nothing quite<br><em>repeats.</em></h2><p>We love the irregularity: brown meeting cream, a dark marking breaking across a pale area, the way hair changes direction when the light catches it. Before we decide on a jacket, we can already imagine a shoulder, a pocket or a panel inside that surface.</p><p>The challenge is to keep that character without letting the garment become a collection of unrelated pieces. Smooth leather offers a pause. A clear silhouette gives the markings somewhere to belong. The Herd and the Collection 002 cowhide studies are our responses to that balance.</p></article><article><p class="eyebrow">02 / African artistry is a practice</p><h2>Our references?<br><em>Our own hands.</em></h2><p>We are making from Nairobi, with the eye, experiences and making skills available here. African artistry is not a single print or a costume we add at the end. It is in the choices we make, the people we work with and the freedom to create something that feels contemporary and personal.</p><p>The board is a working tool, not a list of things to copy. A hide might suggest contrast; a belt, an interesting fastening; an artist, a way of questioning what is already familiar. The finished design still has to earn its place in the ROHENI world.</p></article></section><section class="section board-section"><div class="board-toolbar"><p>Move the material clippings / drag, use arrow keys or shuffle.</p><button type="button" class="text-link" data-shuffle>Shuffle the board ↻</button><button type="button" class="text-link" data-reset-board>Reset arrangement</button></div><div class="inspiration-board"><span class="board-scribble" aria-hidden="true">look closer</span>${boardItems.map(([image,title,note],i)=>`<figure class="board-card" tabindex="0" aria-label="${esc(title)}. Use arrow keys to move this clipping." style="--r:${[-5,4,-3,5,3,-5,4,-3][i]}deg"><img src="assets/images/${image}" alt="${esc(note)}" loading="lazy" draggable="false"><figcaption><strong>${title}</strong><span>${note}</span></figcaption></figure>`).join('')}<div class="board-note"><span>From looking to making</span><p>Where should this marking fall? What can we leave quiet? What changes when the seam curves?</p><a href="journal.html">See our Collection 002 response ↗</a></div></div><p class="credits-note">Material references and ROHENI development imagery.</p></a>.</p></details></section><section class="section creative-influences"><div class="section-head"><div><p class="eyebrow">Creative influences / ways of thinking</p><h2>The thought<br>behind the <em>reference.</em></h2></div><p>Articles that helps explain<br>what we take from these practices.</p></div><div class="influence-grid"><article class="influence-profile"><figure>${photo('inspiration-virgil','Image of Virgil Abloh wearing a denim jacket and hoodie','loading="lazy"')}<figcaption>Virgil Abloh</figcaption></figure><p class="eyebrow">Virgil Abloh / developing a design language</p><h3>Keep looking.<br>Keep <em>making.</em></h3><p>We are drawn to the way Abloh treated familiar objects as starting points. The lesson for us is to study our influences honestly, notice the choices we return to and keep refining a recognisable point of view through making.</p><p>In <em>36 Chapters</em>, writer ab gathers lessons from Abloh’s talks about starting before everything feels perfect, learning from mentors and developing a personal design language. For ROHENI, that connects to repetition with purpose: revisit a curve, a panel or a material until it begins to feel like our own work.</p><a class="text-link" href="https://www.36chapters.com/virgil-ablohs-lessons-for-creatives-6ca91764f90a" target="_blank" rel="noopener noreferrer">Read “Virgil Abloh’s Lessons for Creatives” ↗</a><p class="reading-credit">ab / 36 Chapters / 20 November 2017</p></article><article class="influence-profile">
<figure>
<img src="assets/wisdom%20kaye.jpeg"
alt="Wisdom Kaye wearing a sculptural hat and textured neutral outfit"
loading="lazy">
<figcaption>Wisdom Kaye</figcaption>
</figure>

<p class="eyebrow">Wisdom Kaye / another way to wear it</p>

<h3>Already made.<br>Still <em>unexpected.</em></h3>

<p>What draws us to Wisdom Kaye is his willingness to try the combination you might have dismissed. The layers, the proportions, the textures, you want to look again.</p>

<p>His styling for eBay’s Endless Runway brings that curiosity to pre-loved clothing. At ROHENI, we take that spirit into making: opening up discarded garments, working with the usable fabric and finding combinations worth wearing.</p>

<a class="text-link"
href="https://www.teenvogue.com/story/at-ebays-endless-runway-pre-loved-takes-the-spotlight-with-wisdom-kaye"
target="_blank"
rel="noopener noreferrer">Explore Wisdom’s pre-loved runway ↗</a>

<p class="reading-credit">Skyli Alvarez / Teen Vogue / 12 September 2024</p>
</article></div><p class="credits-note"></p></section>${materialFilm()}`;}

function materialFilm(){return `<section class="section material-film"><div><p class="eyebrow"/p><h2>Look.<br><em>A little closer.</em></h2><p>Before we decide what a piece will become, we spend time with the material. The markings, the worn patches, the colours beside each other.</p><p class="small-text"/p></div><figure><video controls muted loop playsinline preload="none" poster="assets/images/board-denim.png" aria-label="Nine-second animated material study"><source src="assets/video/material-study.mp4" type="video/mp4"></video><figcaption>Denim / cowhide / leather</figcaption></figure></section>`;}
function importChart(data){const series=data.impact.series;return `<figure class="import-chart"><figcaption><span class="eyebrow">National context / annual imports</span><h3>More clothing<br>entering <em>Kenya.</em></h3><p>Secondhand clothing imports, tonnes / 2021–2025</p></figcaption><div class="import-bars" role="img" aria-label="Annual secondhand clothing imports to Kenya: 183,830.1 tonnes in 2021; 177,664.4 in 2022; 198,083.5 in 2023; 230,535.3 in 2024; 250,527.3 in 2025, provisional. Bars begin at zero.">${series.map(x=>`<div class="import-row"><span>${x.year}${x.provisional?'*':''}</span><div class="import-track"><div style="width:${(x.tonnes/260000*100).toFixed(3)}%"></div></div><strong>${Math.round(x.tonnes).toLocaleString('en-GB')}</strong></div>`).join('')}</div><p class="chart-note">Zero-baseline scale / maximum 260,000 tonnes. Labels rounded to whole tonnes. *2025 provisional.</p><details><summary>View the exact data and source</summary><table><caption>Kenya secondhand clothing imports</caption><thead><tr><th scope="col">Year</th><th scope="col">Tonnes</th><th scope="col">Status</th></tr></thead><tbody>${series.map(x=>`<tr><th scope="row">${x.year}</th><td>${x.tonnes.toLocaleString('en-GB',{minimumFractionDigits:1,maximumFractionDigits:1})}</td><td>${x.provisional?'Provisional':'Published'}</td></tr>`).join('')}</tbody></table><a href="content/kenya-secondhand-imports.csv" download>Download the data / CSV ↗</a></details><p class="source-line">Source: Kenya National Bureau of Statistics, <a href="https://www.knbs.or.ke/wp-content/uploads/2026/04/2026-Economic-Survey.pdf" target="_blank" rel="noopener noreferrer">Economic Survey 2026, Table 6.6</a>. These are countrywide imports, not Nairobi waste totals or ROHENI impact.</p></figure>`;}

function missionPage(data){return `<section class="page-intro impact-intro"><p class="eyebrow">Impact / Gikomba, Nairobi and our responsibility</p><h1>The clothes move on.<br>The waste<br><em>stays somewhere.</em></h1><p>Gikomba is part of Nairobi’s everyday economy: a place to find, trade, repair and imagine. Our material choices sit within that reality. What happens to the unwanted clothing matters to the people making a living here, and to everyone making and selling clothes.</p><a class="text-link" href="#secondhand-story">Follow the evidence ↓</a></section><section class="section section-compact impact-opening"><figure>${photo('impact-waste-site','Supplied contextual image of an open waste site with smoke and people sorting mixed waste','loading="eager"')}</figure><div><p class="eyebrow">A useful garment is not waste</p><h2>Reuse matters.<br>So does <em>what is left.</em></h2><p>Secondhand clothing makes a wardrobe more affordable and keeps good garments in circulation. Traders, repairers and makers create value from that trade. We do not want that resourcefulness erased from the conversation.</p><p>The problem is the fraction that cannot find a useful next life: damaged clothing, unsuitable pieces and material that has reached the end of its use. When those rejects accumulate, local communities and waste workers are left handling a problem shaped by a much larger fashion system.</p><p>Kenya’s National Environment Management Authority (NEMA) connects textile waste with blocked drains, water pollution and pressure on waste services. Its 2025 World Cleanup Day focused on textile and fashion waste. <a class="inline-source" href="https://nema.go.ke/world-cleanup-day-2025/" target="_blank" rel="noopener noreferrer">Read NEMA’s account ↗</a></p></div></section><section class="section impact-data" id="secondhand-story"><div><p class="eyebrow">01 / the scale coming in</p><h2>Read the volume.<br><em>Keep the context.</em></h2><p>Kenya imported about 250,527 tonnes of secondhand clothing in 2025, according to provisional figures in the Kenya National Bureau of Statistics’ <em>Economic Survey 2026</em>. The chart shows the same annual series over five years.</p><p>More imports do not tell us, on their own, how much becomes waste. They show the scale of the flow that traders, customers and the systems for reuse and disposal have to handle.</p></div>${importChart(data)}</section><section class="section investigation-section"><div><p class="eyebrow">02 / what an investigation found</p><h2>A bale can carry<br><em>someone else’s problem.</em></h2><p>In its February 2023 <em>Trashion</em> investigation, Changing Markets Foundation reported traders describing 20–50% of the clothing in bales they bought as unsellable. This is an interview-based range, not an official national waste rate.</p><p>The investigation documented low-grade clothing dumped near the Nairobi River and discarded clothing used as fuel. It also described the added pollution burden when synthetic materials enter the waste stream.</p><p>The lesson we take is practical: keeping clothes in use requires more than exporting them. Condition, local demand, sorting and responsibility for what cannot be used all matter.</p><a class="text-link" href="https://changingmarkets.org/report/trashion-the-stealth-export-of-waste-plastic-clothes-to-kenya/" target="_blank" rel="noopener noreferrer">Read Changing Markets’ Trashion report ↗</a></div><figure>${photo('impact-river','Supplied reference photograph of discarded materials along a waterway','loading="lazy"')}<figcaption>Riverbank pollution / supplied reference image. Contextual illustration, not a measurement or a photograph of ROHENI’s own material recovery.</figcaption></figure></section><section class="section impact-map-section"><div><p class="eyebrow">03 / close to the water</p><h2>A market.<br>A river.<br><em>A shared city.</em></h2><p>The supplied map places Gikomba Market alongside the Nairobi River. That proximity helps explain why the conversation must include where unwanted material goes after a bale is opened and sorted.</p><p>A photograph can show an accumulation; it cannot tell us its full source, age or volume. Likewise, the marked boundary on this reference is a visual guide, not a surveyed market boundary or a current pollution map.</p></div><figure><button class="image-button" data-full="assets/images/impact-gikomba-map.webp" data-caption="Map of Gikomba Market alongside the Nairobi River. Reference only; not a surveyed boundary or current pollution map." aria-label="Enlarge the Gikomba and Nairobi River reference map">${photo('impact-gikomba-map','Supplied satellite reference with Gikomba Market outlined in yellow and Nairobi River marked in blue','loading="lazy"')}</button><figcaption>Supplied annotated map / Gikomba Market and Nairobi River. Capture date and original map provider require confirmation.</figcaption></figure></section><section class="section recovery-response"><div class="section-head"><div><p class="eyebrow">04 / what ROHENI can do</p><h2>Start with<br><em>the usable part.</em></h2></div><p>Good intentions still need<br>good material decisions.</p></div><div class="recovery-layout"><figure>${photo('impact-worn-jacket','Supplied reference of a dark jacket with deteriorating material around the shoulders','loading="lazy"')}<figcaption>Condition comes first / a supplied damaged-garment reference. Deterioration can limit whether and how a material can be reused.</figcaption></figure><div><article><span>01</span><h3>Look before cutting</h3><p>We begin with condition, not just colour. A damaged garment may contain usable sections, but not every surface can or should become another product.</p></article><article><span>02</span><h3>Design for what is available</h3><p>Kaleidoscope brings recovered denim and factory cutoffs into visible patchwork. Irregular pieces become part of the composition, with Kenyan making turning that arrangement into something wearable.</p></article><article><span>03</span><h3>Give the smaller pieces a role</h3><p>Accessories offer another scale for suitable remnants. Collection 002 extends the exploration into a secondhand-material hoodie and a recycled T-shirt direction, with the final material specifications still in development.</p></article><article><span>04</span><h3>Record what we actually use</h3><p>Our next step is consistent material records: source, weight used, offcuts left and what happens to them. We have not yet established a verified waste-diversion or carbon-saving total.</p></article><a class="text-link" href="project.html?id=kaleidoscope">See Kaleidoscope / the patchwork response ↗</a></div></div></section><section class="section impact-accountability"><h2>The goal is clear.<br>The accounting<br>must be <em>clear too.</em></h2><p>We want to help reduce textile waste and show the value of African artistry through clothes people love. Our portfolio documents a creative practice and its intentions. It does not claim that one studio can clean up Gikomba or that every material we use was recovered there.</p><a class="text-link" href="journal.html">See what Collection 002 is developing ↗</a></section><section class="section section-compact impact-sources"><p class="eyebrow">Sources / checked 2 November 2026</p><h2>Read beyond<br><em>the portfolio.</em></h2><ol><li><a href="https://www.knbs.or.ke/wp-content/uploads/2026/04/2026-Economic-Survey.pdf" target="_blank" rel="noopener noreferrer">Kenya National Bureau of Statistics / Economic Survey 2026, Table 6.6</a><p>Annual quantities of principal imports, 2021–2025. Secondhand clothing measured in tonnes; 2025 provisional. National data, not city-level waste data.</p></li><li><a href="https://changingmarkets.org/report/trashion-the-stealth-export-of-waste-plastic-clothes-to-kenya/" target="_blank" rel="noopener noreferrer">Changing Markets Foundation / Trashion, February 2023</a><p>Investigation into used-clothing quality, trade and waste in Kenya. The 20–50% range comes from interviewed traders and is not combined with the later import series.</p></li><li><a href="https://nema.go.ke/world-cleanup-day-2025/" target="_blank" rel="noopener noreferrer">National Environment Management Authority / World Cleanup Day 2025</a><p>Kenyan environmental authority’s account of textile waste, urban drainage and pollution.</p></li></ol><details><summary>Photograph and map notes</summary><p>Context photographs and the annotated map were supplied for this portfolio. They are not presented as original ROHENI documentary photography, current measurements or proof of a particular garment’s source. Original photographer, map-provider credits and reuse permissions remain to confirm.</p></details></section>`;}

function setupStudioPlay(){if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const headings=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('heading-arrived');headings.unobserve(e.target);}}),{threshold:.15});document.querySelectorAll('main h2').forEach(h=>headings.observe(h));}document.querySelectorAll('canvas.bent-logo').forEach(c=>{const logo=new Image();logo.onload=()=>{const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';const sw=1517,sh=602,dw=1100,dh=dw*sh/sw;for(let x=0;x<dw;x++){const n=(x-dw/2)/(dw/2);ctx.drawImage(logo,129+x*sw/dw,164,sw/dw+1,sh,50+x,25+90*n*n,1.8,dh);}};logo.src='assets/images/roheni-logo.png';});const board=document.querySelector('.inspiration-board');let shuffle=0;document.querySelector('[data-shuffle]')?.addEventListener('click',()=>{shuffle++;board.querySelectorAll('.board-card').forEach((c,i)=>{c.style.setProperty('--r',((i*7+shuffle*5)%15-7)+'deg');c.style.setProperty('--dx',((i+shuffle)%3-1)*12+'px');c.style.setProperty('--dy',((i+shuffle)%2?10:-10)+'px');});});document.querySelector('[data-reset-board]')?.addEventListener('click',()=>board.querySelectorAll('.board-card').forEach((c,i)=>{c.style.setProperty('--dx','0px');c.style.setProperty('--dy','0px');c.style.setProperty('--r',[-5,4,-3,5,3,-5,4,-3][i]+'deg');}));board?.querySelectorAll('.board-card').forEach(card=>{let start;const move=(x,y)=>{card.style.setProperty('--dx',Math.max(-50,Math.min(50,x))+'px');card.style.setProperty('--dy',Math.max(-60,Math.min(60,y))+'px');};card.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;start={x:e.clientX,y:e.clientY,dx:parseFloat(card.style.getPropertyValue('--dx'))||0,dy:parseFloat(card.style.getPropertyValue('--dy'))||0};card.setPointerCapture(e.pointerId);card.classList.add('dragging');});card.addEventListener('pointermove',e=>{if(start)move(start.dx+e.clientX-start.x,start.dy+e.clientY-start.y);});const stop=()=>{start=null;card.classList.remove('dragging');};card.addEventListener('pointerup',stop);card.addEventListener('pointercancel',stop);card.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const x=parseFloat(card.style.getPropertyValue('--dx'))||0,y=parseFloat(card.style.getPropertyValue('--dy'))||0;move(x+(e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0),y+(e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0));});});document.querySelectorAll('[data-cycle-material]').forEach(b=>{let n=0;b.addEventListener('click',()=>{n=(n+1)%3;const names=['rethink it','denim → design','remnant → piece'];b.querySelector('small').textContent=names[n];b.querySelector('span').style.transform=`rotate(${n*120}deg)`;});});if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{const v=e.target;if(e.isIntersecting&&!motionPaused&&v.dataset.userPaused!=='true')v.play().catch(()=>{});else pauseFilm(v);}),{threshold:.3});document.querySelectorAll('.material-film video').forEach(v=>observer.observe(v));}document.querySelectorAll('.material-film video').forEach(v=>{v.addEventListener('pause',()=>{if(v.dataset.autoPause==='true')delete v.dataset.autoPause;else v.dataset.userPaused='true';});v.addEventListener('play',()=>{v.dataset.userPaused='false';});});}
function pauseFilm(v){if(!v.paused){v.dataset.autoPause='true';v.pause();}}
let motionPaused=matchMedia('(prefers-reduced-motion: reduce)').matches;
function toggleMotion(){motionPaused=!motionPaused;applyMotion();}
function applyMotion(){document.querySelectorAll('.material-film video').forEach(v=>{if(motionPaused)pauseFilm(v);else if(v.dataset.userPaused!=='true'&&v.getBoundingClientRect().top<innerHeight&&v.getBoundingClientRect().bottom>0)v.play().catch(()=>{});});document.documentElement.classList.toggle('motion-paused',motionPaused);document.querySelectorAll('.motion-control').forEach(b=>{b.setAttribute('aria-pressed',String(motionPaused));if(b.classList.contains('motion-control'))b.textContent=motionPaused?'Resume motion ▷':'Pause motion Ⅱ';else b.setAttribute('aria-label',motionPaused?'Resume decorative motion':'Pause decorative motion');});}
function setupAppearance(){let choice='white';try{choice=localStorage.getItem('roheni-theme-v3')||'white';}catch{}const setTheme=value=>{if(!['red','white','dark'].includes(value))value='white';document.documentElement.dataset.theme=value;document.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===value)));document.querySelector('meta[name="theme-color"]')?.setAttribute('content',({red:'#7a0000',white:'#fefefe',dark:'#2e2e2e'})[value]);try{localStorage.setItem('roheni-theme-v3',value);}catch{}};setTheme(choice);document.querySelectorAll('[data-theme-choice]').forEach(b=>b.addEventListener('click',()=>setTheme(b.dataset.themeChoice)));document.querySelector('.motion-control')?.addEventListener('click',toggleMotion);applyMotion();}
async function init(){try{const response=await fetch('content/site.json');if(!response.ok)throw new Error('Content unavailable');const data=await response.json();chrome(data);setupAppearance();const views={index:()=>home(data),collections:()=>`<section class="page-intro"><p class="eyebrow">Collection 001</p><h1>Clothes with<br>another <em>story.</em></h1><p>Collection 001 brings together Kaleidoscope denim jackets, The Herd cowhide and leather pieces, the AtIr and Adwoa women’s sets, and accessories. Different silhouettes, connected by our love of contrast, Kenyan making and overlooked materials.</p></section><section class="section section-compact">${collectionChapters(data)}</section>`,about:()=>about(data),inspiration:()=>inspirationPage(),mission:()=>missionPage(data),impact:()=>missionPage(data),studio:()=>studio(data),journal:()=>journal(data),process:()=>processPage(data),project:()=>project(data),contact:()=>contact(data)};main.innerHTML=(views[page]||views.index)();
 setupStudioPlay();setupCarousel();applyMotion();if(location.hash){try{const anchor=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(anchor)requestAnimationFrame(()=>anchor.scrollIntoView());}catch{}}setupSoundtrack();setupEventFilm();
 document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('#development-gallery figure').forEach(f=>{f.hidden=value!=='All'&&f.dataset.kind!==value;});}));
 const dialog=document.getElementById('lightbox');let previous;
 document.querySelectorAll('[data-full]').forEach(button=>button.addEventListener('click',()=>{previous=button;dialog.querySelector('img').src=button.dataset.full;dialog.querySelector('img').alt=button.dataset.caption;dialog.querySelector('p').textContent=button.dataset.caption;dialog.showModal();}));dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>previous?.focus());dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
 }catch(error){console.error(error);main.innerHTML='<section class="page-intro"><h1>The studio is taking a moment.</h1><p>Please refresh, or email <a href="mailto:rohenioriginals@gmail.com">rohenioriginals@gmail.com</a>.</p></section>';}}
init();

function setupSoundtrack(){
 const button=document.querySelector('.flying-play');if(!button)return;
 const audio=new Audio('assets/media/roheni-soundtrack.m4a');audio.preload='none';audio.volume=.35;
 const panel=document.createElement('div');panel.className='soundtrack-panel';panel.innerHTML=`<div class="soundtrack-track"><span class="soundtrack-equaliser" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span><strong>SEEN</strong><small> by Jay Versace </small></span></div><label class="soundtrack-volume">Volume <input type="range" min="0" max="100" step="1" value="35" aria-label="Soundtrack volume"><output>35%</output></label><span class="soundtrack-feedback" role="status"></span>`;button.after(panel);
 const status=panel.querySelector('.soundtrack-feedback'),slider=panel.querySelector('input'),output=panel.querySelector('output');
 const sync=()=>{const playing=!audio.paused;button.setAttribute('aria-pressed',String(playing));button.setAttribute('aria-label',playing?'Pause SEEN by Jay Versace':'Play SEEN by Jay Versace');button.querySelector('span').textContent=playing?'Ⅱ':'▷';button.classList.toggle('soundtrack-playing',playing);panel.classList.toggle('is-playing',playing);};sync();
 slider.addEventListener('input',()=>{audio.volume=Number(slider.value)/100;output.textContent=slider.value+'%';});
 button.addEventListener('click',async()=>{if(!audio.paused){audio.pause();return;}try{await audio.play();status.textContent='';}catch{status.textContent='Audio unavailable. Please try again.';sync();}});
 audio.addEventListener('play',sync);audio.addEventListener('pause',sync);audio.addEventListener('ended',sync);addEventListener('pagehide',()=>audio.pause());document.addEventListener('visibilitychange',()=>{if(document.hidden)audio.pause();});
}
function setupEventFilm(){const video=document.querySelector('.event-film video');if(!video)return;const sound=document.querySelector('.event-sound-toggle');const soundLabel=()=>{if(sound){sound.textContent=video.muted?'Sound on ♫':'Sound off ♫';sound.setAttribute('aria-pressed',String(!video.muted));}};sound?.addEventListener('click',()=>{video.muted=!video.muted;if(!video.muted){video.volume=.5;video.play().catch(()=>{});}soundLabel();});video.addEventListener('volumechange',soundLabel);soundLabel();let visible=false,userPaused=false,automatic=false;const stop=()=>{if(!video.paused){automatic=true;video.pause();}};video.addEventListener('pause',()=>{if(!automatic)userPaused=true;automatic=false;});video.addEventListener('play',()=>{userPaused=false;});const update=()=>{if(!visible||document.hidden||motionPaused){stop();return;}if(!userPaused&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!navigator.connection?.saveData)video.play().catch(()=>{});};const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;update();},{threshold:.25});observer.observe(video);document.addEventListener('visibilitychange',update);document.querySelector('.motion-control')?.addEventListener('click',update);}
